import{_ as t,o,c as i,ae as a}from"./chunks/framework.DBosx3SP.js";const h=JSON.parse('{"title":"AI Survey: Web Accessibility","description":"","frontmatter":{},"headers":[],"relativePath":"ux/web-accessibility.md","filePath":"ux/web-accessibility.md","lastUpdated":1792996843000}'),l={name:"ux/web-accessibility.md"};function r(s,e,n,c,u,d){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="ai-survey-web-accessibility" tabindex="-1">AI Survey: Web Accessibility <a class="header-anchor" href="#ai-survey-web-accessibility" aria-label="Permalink to &quot;AI Survey: Web Accessibility&quot;">​</a></h1><h2 id="web-accessibility-and-the-problem-of-exclusively-relying-on-development-tools-to-achieve-it" tabindex="-1">Web Accessibility and the problem of exclusively relying on development tools to achieve it <a class="header-anchor" href="#web-accessibility-and-the-problem-of-exclusively-relying-on-development-tools-to-achieve-it" aria-label="Permalink to &quot;Web Accessibility and the problem of exclusively relying on development tools to achieve it&quot;">​</a></h2><p>Oliver Andersson 2025</p><p>Hover interaction is problematic in accessibility - reflected in WCAG 2.1, Success Criterion 1.4.13, Content on Hover or Focus</p><p><a href="https://www.w3.org/WAI/WCAG22/Understanding/content-on-hover-or-focus.html" target="_blank" rel="noreferrer">https://www.w3.org/WAI/WCAG22/Understanding/content-on-hover-or-focus.html</a></p><blockquote><p>&quot;content triggered by hover or focus can be dismissed without moving the pointer to prevent having to renavigate to the content.&quot;</p></blockquote><hr><p><strong>Enhancing statistical chart accessibility for people with low vision: insights from a user test</strong></p><ul><li>recommendation for chart types</li></ul><hr><p><strong>Probing Projections: Interaction Techniques for Interpreting Arrangements and Errors of Dimensionality Reductions</strong></p><p>On geo-charts, draw sub-plot inside tooltip</p><hr><p><strong>Design Patterns and Trade-Offs in Responsive Visualization for Communication</strong></p><p>Many patterns for responsive design</p><hr><h3 id="tooltip-design-guidelines" tabindex="-1">Tooltip Design Guidelines <a class="header-anchor" href="#tooltip-design-guidelines" aria-label="Permalink to &quot;Tooltip Design Guidelines&quot;">​</a></h3><ol><li>Don&#39;t cover the data point — tooltips obscuring chart elements was a major complaint (Alcaraz-Martínez 2025)</li><li>Close spatial proximity — place tooltip near the element, not in a sidebar (Vaniea 2012, Gestalt principles)</li><li>On-demand triggering — users wanted control over when tooltips appear, not just auto-hover (Alcaraz-Martínez 2025)</li><li>Show exact data values — users relied on tooltips to read precise numbers (Alcaraz-Martínez 2025)</li><li>Allow zoomable/resizable text — important for accessibility (Alcaraz-Martínez 2025)</li><li>Explain &quot;why&quot; — for scatter plots, show why points are positioned where they are (Stahnke 2015)</li></ol><hr><h3 id="key-findings-for-hover-tooltip-implementation" tabindex="-1">Key Findings for Hover Tooltip Implementation <a class="header-anchor" href="#key-findings-for-hover-tooltip-implementation" aria-label="Permalink to &quot;Key Findings for Hover Tooltip Implementation&quot;">​</a></h3><p><strong>From &quot;Probing Projections&quot; (Stahnke et al. 2015)</strong></p><p>Tooltip Content Design (Fig. 2):</p><ul><li>Show absolute values + standard deviations for each dimension</li><li>Include graphical representations (mini bar charts showing deviation from mean)</li><li>Color-code bars: red/blue for positive/negative deviation, saturation for magnitude</li></ul><p>Tooltip for Comparisons (Fig. 3):</p><ul><li>When comparing groups, show MEAN and DENSITY columns</li><li>Include small density plots inline</li></ul><p>User Study Findings:</p><ul><li>&quot;Tooltips with data details were brought up by all participants throughout all tasks&quot;</li><li>&quot;Some negatively remarked that the tooltips are not as useful as they could be, because they overlapped the projection area&quot;</li><li>Data distribution as part of tooltip was used throughout all tasks</li></ul><hr><p><strong>From &quot;Enhancing Statistical Chart Accessibility&quot; (Alcaraz-Martínez 2025)</strong></p><p>Key Finding:</p><blockquote><p>&quot;Tooltips were highly valued by all users, but their implementation must be improved to avoid covering up significant parts of the charts when displayed.&quot;</p></blockquote><p>User Observations (Table 10):</p><ul><li>Users &quot;constantly uses the tooltips&quot; in accessible version</li><li>&quot;Hovers the mouse pointer over the bars, triggering the tooltip, and zooms in on the screen to read the data&quot;</li><li>Users preferred accessible version because of &quot;data labels, hover effects and tooltips&quot;</li></ul><p>H16 Visible Focus:</p><ul><li>When element receives focus, there must be visual indication</li></ul><h3 id="key-requirements" tabindex="-1">Key Requirements <a class="header-anchor" href="#key-requirements" aria-label="Permalink to &quot;Key Requirements&quot;">​</a></h3><ol><li>Never cover the data point being examined</li><li>Show exact values (x, y, label)</li><li>Visual focus indicator on the hovered point (highlight/ring)</li><li>Support on-demand triggering for accessibility</li><li>High contrast solid background</li></ol><h3 id="sourced-claims" tabindex="-1">Sourced Claims <a class="header-anchor" href="#sourced-claims" aria-label="Permalink to &quot;Sourced Claims&quot;">​</a></h3><blockquote><ol><li>&quot;Tooltips were highly valued by all users, but their implementation must be improved to avoid covering up significant parts of the charts&quot;</li><li>User 6&#39;s complaint: &quot;Tooltips are nice, but with a zoom applied they cover [the chart]&quot;</li><li>User 8 at 500% zoom: &quot;finds the tooltips bothersome&quot; - they obscure the view</li><li>Design recommendations (p.3013): <ul><li>(a) Tooltips should be zoomable</li><li>(b) Offer tooltips callable on demand (not always auto-triggered)</li><li>Tooltips should not obscure chart elements</li><li>Reference: NN/g Nielsen Norman Group tooltip guidelines</li></ul></li><li>Implementation note: &quot;when implementing tooltips, the following considerations should be taken into account: (a) tooltips should [not cover elements]&quot;</li></ol></blockquote><p><strong>Paper</strong>: Alcaraz-Martínez, R., Ribera, M., Adeva-Fillol, A., &amp; Pascual-Almenara, A. (2025). <em>Enhancing statistical chart accessibility for people with low vision: insights from a user test.</em> Universal Access in the Information Society, 24, 2981–3019.<br><a href="https://doi.org/10.1007/s10209-024-01111-4" target="_blank" rel="noreferrer">https://doi.org/10.1007/s10209-024-01111-4</a></p><table tabindex="0"><thead><tr><th>#</th><th>Claim</th><th>Source</th></tr></thead><tbody><tr><td>1</td><td>&quot;tooltips were highly valued by all users, but their implementation must be improved to avoid covering up significant parts of the charts when displayed&quot;</td><td>Abstract, p. 2981</td></tr><tr><td>2</td><td>&quot;Tooltips are nice, but with a zoom applied they cover [the chart]&quot;</td><td>User 6 quote, Section 5 Discussion, p. 3011</td></tr><tr><td>3</td><td>User 8 &quot;finds the tooltips bothersome&quot; at 500% zoom</td><td>Table 10 (User 8, Line chart), p. 3009</td></tr><tr><td>4a</td><td>&quot;offer zoomable tooltips&quot;</td><td>Insight (b), Section 5 Discussion, p. 3013</td></tr><tr><td>4b</td><td>&quot;but callable on demand&quot;</td><td>Insight (b), Section 5 Discussion, p. 3013</td></tr><tr><td>5</td><td>NN/g tooltip guidelines reference</td><td>Reference [95], p. 3018: Joyce, A.: Tooltip guidelines. NN/g Nielsen Norman Group. <a href="https://www.nngroup.com/articles/tooltip-guidelines" target="_blank" rel="noreferrer">https://www.nngroup.com/articles/tooltip-guidelines</a></td></tr></tbody></table><blockquote><p><strong>Note</strong>: Claim #5 &quot;tooltips should [not cover elements]&quot; — the exact phrasing was not found in the extracted text. The paper implies this through the user complaints but doesn&#39;t state it as an explicit implementation guideline.</p></blockquote>',42)])])}const b=t(l,[["render",r]]);export{h as __pageData,b as default};
